/**
 * Generates supabase/seed.sql from the same catalogue the mock backend uses, so both
 * data sources stay in sync. Run with: npm run db:seed-sql
 */
import { writeFileSync } from 'node:fs';
import { CATEGORIES, COUPONS, PRODUCTS } from '../src/services/mock/seed';

const q = (v: unknown): string => {
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return `array[${v.map(q).join(', ')}]::text[]`;
  return `'${String(v).replace(/'/g, "''")}'`;
};

const lines: string[] = [
  '-- Generated by scripts/generate-seed-sql.ts — do not edit by hand.',
  'begin;',
];

// parents first so the self-referencing FK is satisfied
const cats = [...CATEGORIES].sort(
  (a, b) => Number(Boolean(a.parent_id)) - Number(Boolean(b.parent_id)),
);
for (const c of cats) {
  lines.push(
    `insert into public.categories (id, name, slug, parent_id, image_url, description) values (${[c.id, c.name, c.slug, c.parent_id, c.image_url, c.description ?? null].map(q).join(', ')}) on conflict (id) do nothing;`,
  );
}

for (const p of PRODUCTS) {
  lines.push(
    `insert into public.products (id, slug, title, description, brand, category_id, gender, price, compare_at_price, material, care, details, status, rating, review_count, is_new, is_best_seller, created_at) values (${[
      p.id,
      p.slug,
      p.title,
      p.description,
      p.brand,
      p.category_id,
      p.gender,
      p.price,
      p.compare_at_price,
      p.material,
      p.care,
      p.details,
      p.status,
      p.rating,
      p.review_count,
      p.is_new,
      p.is_best_seller,
      p.created_at,
    ]
      .map(q)
      .join(', ')}) on conflict (id) do nothing;`,
  );
  for (const v of p.variants) {
    lines.push(
      `insert into public.product_variants (id, product_id, color, color_hex, size, sku, price, inventory_count, image_urls) values (${[
        v.id,
        v.product_id,
        v.color,
        v.color_hex,
        v.size,
        v.sku,
        v.price,
        v.inventory_count,
        v.image_urls,
      ]
        .map(q)
        .join(', ')}) on conflict (id) do nothing;`,
    );
  }
}

for (const c of COUPONS) {
  lines.push(
    `insert into public.coupons (code, type, value, min_subtotal, expires_at, description, usage_limit, times_used, is_public) values (${[
      c.code,
      c.type,
      c.value,
      c.min_subtotal,
      c.expires_at,
      c.description,
      c.usage_limit,
      c.times_used,
      c.is_public,
    ]
      .map(q)
      .join(', ')}) on conflict (code) do nothing;`,
  );
}

lines.push('commit;', '');
writeFileSync(new URL('../supabase/seed.sql', import.meta.url), lines.join('\n'));
console.log(
  `Wrote supabase/seed.sql (${CATEGORIES.length} categories, ${PRODUCTS.length} products, ${COUPONS.length} coupons)`,
);
